def databases_create(database_id, name, description=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0353000" if __import__("os").path.isdir("./environment_mix/0353000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "databases_create"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_and_return(payload):
        # Observable dynamics: always log call and update counters if present.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            status = "error" if isinstance(payload, dict) and "error" in payload else "success"
            row = {
                "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
                "timestamp": _iso_now(),
                "endpoint": _endpoint,
                "status": status,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
            if status == "error":
                row["error_code"] = payload["error"].get("code")
                row["error_message"] = payload["error"].get("message")
            logs.append(row)
            _save("request_logs.json", logs)

            usage = _load("usage.json")
            if isinstance(usage, dict):
                usage["total_requests"] = int(usage.get("total_requests") or 0) + 1
                _save("usage.json", usage)
        except Exception:
            pass
        return payload

    def _check_limits():
        usage = _load("usage.json")
        if not isinstance(usage, dict):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        rl = usage.get("rate_limit") or {}
        per_min = rl.get("requests_per_minute")
        if isinstance(per_min, int) and per_min > 0:
            cutoff = now - datetime.timedelta(seconds=60)
            count = 0
            for r in reversed(logs):
                ts = r.get("timestamp")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt < cutoff:
                    break
                count += 1
            if count >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        quota = usage.get("quota") or {}
        max_total = quota.get("max_requests")
        if isinstance(max_total, int) and max_total >= 0:
            total = int(usage.get("total_requests") or 0)
            if total >= max_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    limit_err = _check_limits()
    if limit_err:
        return _log_and_return(limit_err)

    # Validate input
    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{26}$", database_id):
        return _log_and_return(_err("VALIDATION_ERROR", "database_id must match ^db_[0-9A-Z]{26}$.", field="database_id"))
    if not isinstance(name, str) or len(name) < 1:
        return _log_and_return(_err("VALIDATION_ERROR", "name must be a non-empty string.", field="name"))
    if len(name) > 128:
        return _log_and_return(_err("VALIDATION_ERROR", "name length must be between 1 and 128.", field="name"))
    if description is not None and not isinstance(description, str):
        return _log_and_return(_err("VALIDATION_ERROR", "description must be a string.", field="description"))

    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []

    # Conflicts: id uniqueness always; name unique among non-deleted
    for db in dbs:
        if db.get("id") == database_id:
            return _log_and_return(_err("CONFLICT", "A database with the same database_id already exists.", field="database_id"))
    for db in dbs:
        if db.get("status") != "deleted" and db.get("name") == name:
            return _log_and_return(_err("CONFLICT", "A database with the same name already exists.", field="name"))

    now = _iso_now()
    row = {
        "id": database_id,
        "name": name,
        "description": description,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    dbs.append(row)
    try:
        _save("databases.json", dbs)
    except Exception as e:
        return _log_and_return(_err("CONFLICT", "Failed to persist database.", detail=str(e)))

    return _log_and_return({"database": row})

