    _endpoint = "databases_create_datetime_attribute"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_dt(val, field):
        if val is None:
            return None, None
        if not isinstance(val, str) or not val:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 datetime.", field=field)
        try:
            datetime.datetime.fromisoformat(val.replace("Z", "+00:00"))
            return val, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 datetime.", field=field)

