    if e: return _log_and_return(e)

    if min_s is not None and max_s is not None:
        try:
            dmin = datetime.datetime.fromisoformat(min_s.replace("Z", "+00:00"))
            dmax = datetime.datetime.fromisoformat(max_s.replace("Z", "+00:00"))
            if dmin > dmax:
                return _log_and_return(_err("VALIDATION_ERROR", "min must be less than or equal to max.", field="min"))
        except Exception:
            return _log_and_return(_err("VALIDATION_ERROR", "min/max must be valid ISO 8601 datetimes.", field="min"))

    dbs = _load("databases.json")
