def databases_create_document(database_id, collection_id, document_id, data, permissions=None, **_extra):
    import json, os, datetime, re, time, ipaddress
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0353000" if __import__("os").path.isdir("./environment_mix/0353000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _endpoint = "databases_create_document"

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_and_return(payload):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            status = "error" if isinstance(payload, dict) and "error" in payload else "success"
            row = {"id": f"req_{int(time.time()*1000)}_{len(logs)+1}", "timestamp": _iso_now(), "endpoint": _endpoint,
                   "status": status, "latency_ms": int((time.time() - _t0) * 1000)}
            if status == "error":
                row["error_code"] = payload["error"].get("code")
                row["error_message"] = payload["error"].get("message")
            logs.append(row)
            _save("request_logs.json", logs)
            usage = _load("usage.json")
            if isinstance(usage, dict):
                usage["total_requests"] = int(usage.get("total_requests") or 0) + 1
                _save("usage.json", usage)
        except Exception:
            pass
        return payload

    def _check_limits():
        usage = _load("usage.json")
        if not isinstance(usage, dict): return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        rl = usage.get("rate_limit") or {}
        per_min = rl.get("requests_per_minute")
        if isinstance(per_min, int) and per_min > 0:
            cutoff = now - datetime.timedelta(seconds=60)
            c = 0
            for r in reversed(logs):
                ts = r.get("timestamp")
                if not isinstance(ts, str): continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt < cutoff: break
                c += 1
            if c >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded.")
        quota = usage.get("quota") or {}
        mx = quota.get("max_requests")
        if isinstance(mx, int) and mx >= 0:
            if int(usage.get("total_requests") or 0) >= mx:
                return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    def _is_iso_datetime(s):
        if not isinstance(s, str) or not s:
            return False
        try:
            datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return True
        except Exception:
            return False

    def _validate_scalar(attr_type, v, attr):
        # returns error message string or None
        if v is None:
            return None
        if attr_type == "string":
            if not isinstance(v, str):
                return "must be a string"
            mn, mx = attr.get("min"), attr.get("max")
            if isinstance(mn, (int, float)) and len(v) < int(mn):
                return f"length must be >= {int(mn)}"
            if isinstance(mx, (int, float)) and len(v) > int(mx):
                return f"length must be <= {int(mx)}"
            return None
        if attr_type == "integer":
            if not isinstance(v, int) or isinstance(v, bool):
                return "must be an integer"
            mn, mx = attr.get("min"), attr.get("max")
            if mn is not None:
                if not isinstance(mn, int):
                    try:
                        if float(mn).is_integer(): mn = int(mn)
                        else: return "min constraint is invalid on schema"
                    except Exception:
                        return "min constraint is invalid on schema"
                if v < mn: return f"must be >= {mn}"
            if mx is not None:
                if not isinstance(mx, int):
                    try:
                        if float(mx).is_integer(): mx = int(mx)
                        else: return "max constraint is invalid on schema"
                    except Exception:
                        return "max constraint is invalid on schema"
                if v > mx: return f"must be <= {mx}"
            return None
        if attr_type == "float":
            if not isinstance(v, (int, float)) or isinstance(v, bool):
                return "must be a number"
            v = float(v)
            mn, mx = attr.get("min"), attr.get("max")
            if isinstance(mn, (int, float)) and v < float(mn):
                return f"must be >= {mn}"
            if isinstance(mx, (int, float)) and v > float(mx):
                return f"must be <= {mx}"
            return None
        if attr_type == "boolean":
            if not isinstance(v, bool):
                return "must be a boolean"
            return None
        if attr_type == "datetime":
            if not isinstance(v, str) or not _is_iso_datetime(v):
                return "must be an ISO 8601 datetime string"
            mn, mx = attr.get("min"), attr.get("max")
            try:
                dv = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                if isinstance(mn, str) and _is_iso_datetime(mn):
                    dmn = datetime.datetime.fromisoformat(mn.replace("Z", "+00:00"))
                    if dv < dmn: return f"must be >= {mn}"
                if isinstance(mx, str) and _is_iso_datetime(mx):
                    dmx = datetime.datetime.fromisoformat(mx.replace("Z", "+00:00"))
                    if dv > dmx: return f"must be <= {mx}"
            except Exception:
                return "must be an ISO 8601 datetime string"
            return None
        if attr_type == "email":
            if not isinstance(v, str):
                return "must be a string"
            if not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", v):
                return "must be a valid email"
            mn, mx = attr.get("min"), attr.get("max")
            if isinstance(mn, (int, float)) and len(v) < int(mn):
                return f"length must be >= {int(mn)}"
            if isinstance(mx, (int, float)) and len(v) > int(mx):
                return f"length must be <= {int(mx)}"
            return None
        if attr_type == "url":
            if not isinstance(v, str):
                return "must be a string"
            if not re.match(r"^https?://", v):
                return "must be a valid URL"
            mn, mx = attr.get("min"), attr.get("max")
            if isinstance(mn, (int, float)) and len(v) < int(mn):
                return f"length must be >= {int(mn)}"
            if isinstance(mx, (int, float)) and len(v) > int(mx):
                return f"length must be <= {int(mx)}"
            return None
        if attr_type == "ip":
            if not isinstance(v, str):
                return "must be a string"
            try:
                ipaddress.ip_address(v)
            except Exception:
                return "must be a valid IP address"
            mn, mx = attr.get("min"), attr.get("max")
            if isinstance(mn, (int, float)) and len(v) < int(mn):
                return f"length must be >= {int(mn)}"
            if isinstance(mx, (int, float)) and len(v) > int(mx):
                return f"length must be <= {int(mx)}"
            return None
        if attr_type == "enum":
            allowed = attr.get("enum_values")
            if not isinstance(allowed, list) or not allowed:
                return "enum schema is invalid"
            if not isinstance(v, str):
                return "must be a string"
            if v not in allowed:
                return "must be one of the allowed enum values"
            return None
        if attr_type == "relationship":
            # store as string or list of strings typically; accept string id(s)
            if isinstance(v, str):
                return None
            return "must be a string reference id"
        return None

    limit_err = _check_limits()
    if limit_err:
        return _log_and_return(limit_err)

    # Validate inputs
    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{26}$", database_id):
        return _log_and_return(_err("VALIDATION_ERROR", "database_id must match ^db_[0-9A-Z]{26}$.", field="database_id"))
    if not isinstance(collection_id, str) or not re.match(r"^col_[0-9A-Z]{26}$", collection_id):
        return _log_and_return(_err("VALIDATION_ERROR", "collection_id must match ^col_[0-9A-Z]{26}$.", field="collection_id"))
    if not isinstance(document_id, str) or not re.match(r"^doc_[0-9A-Z]{26}$", document_id):
        return _log_and_return(_err("VALIDATION_ERROR", "document_id must match ^doc_[0-9A-Z]{26}$.", field="document_id"))
    if not isinstance(data, dict):
        return _log_and_return(_err("VALIDATION_ERROR", "data must be a JSON object.", field="data"))
    if permissions is not None and not isinstance(permissions, dict):
        return _log_and_return(_err("VALIDATION_ERROR", "permissions must be an object when provided.", field="permissions"))

    dbs = _load("databases.json")
    cols = _load("collections.json")
    attrs = _load("attributes.json")
    idxs = _load("indexes.json")
    docs = _load("documents.json")
    if not isinstance(dbs, list): dbs = []
    if not isinstance(cols, list): cols = []
    if not isinstance(attrs, list): attrs = []
    if not isinstance(idxs, list): idxs = []
    if not isinstance(docs, list): docs = []

    db = next((d for d in dbs if d.get("id") == database_id and d.get("status") != "deleted"), None)
    if not db:
        return _log_and_return(_err("NOT_FOUND", "Database not found.", field="database_id"))
    col = next((c for c in cols if c.get("id") == collection_id and c.get("database_id") == database_id and c.get("status") != "deleted"), None)
    if not col:
        return _log_and_return(_err("NOT_FOUND", "Collection not found.", field="collection_id"))
    if col.get("status") != "active":
        return _log_and_return(_err("INVALID_TRANSITION", "Collection is not active.", field="collection_id"))
    if not bool(col.get("enabled")):
        return _log_and_return(_err("INVALID_TRANSITION", "Collection is disabled and cannot accept writes.", field="collection_id"))
    if not bool(col.get("document_security")) and permissions is not None:
        return _log_and_return(_err("VALIDATION_ERROR", "permissions must be null when collection.document_security is false.", field="permissions"))

    # Document id uniqueness (do not allow reuse even if deleted)
    for d in docs:
        if d.get("id") == document_id:
            return _log_and_return(_err("CONFLICT", "A document with the same document_id already exists.", field="document_id"))

    active_attrs = [a for a in attrs if a.get("collection_id") == collection_id and a.get("status") == "active"]
    attr_by_key = {a.get("key"): a for a in active_attrs if isinstance(a.get("key"), str)}

    # Apply defaults for missing fields, and validate
    final = dict(data)
    for k, a in attr_by_key.items():
        if k not in final and a.get("default_value") is not None:
            final[k] = a.get("default_value")

    for k, a in attr_by_key.items():
        if a.get("required") is True:
            if k not in final or final.get(k) is None:
                return _log_and_return(_err("VALIDATION_ERROR", f"Missing required attribute '{k}'.", field=k))

    # Validate values for known attributes; allow extra fields (Appwrite permits dynamic fields but schema governs validation; here validate only schema keys)
    for k, a in attr_by_key.items():
        v = final.get(k, None)
        if v is None:
            continue
        is_array = bool(a.get("array"))
        at = a.get("type")
        if is_array:
            if not isinstance(v, list):
                return _log_and_return(_err("VALIDATION_ERROR", f"Attribute '{k}' must be an array.", field=k))
            for item in v:
                msg = _validate_scalar(at, item, a)
                if msg:
                    return _log_and_return(_err("VALIDATION_ERROR", f"Attribute '{k}' {msg}.", field=k))
        else:
            msg = _validate_scalar(at, v, a)
            if msg:
                return _log_and_return(_err("VALIDATION_ERROR", f"Attribute '{k}' {msg}.", field=k))

    # Unique indexes enforcement (active unique indexes only), across active documents only
    unique_indexes = [ix for ix in idxs if ix.get("collection_id") == collection_id and ix.get("status") == "active" and ix.get("type") == "unique"]
    for ix in unique_indexes:
        keys = ix.get("attributes")
        if not isinstance(keys, list) or not keys:
            continue
        tup = tuple(final.get(k) for k in keys)
        for od in docs:
            if od.get("collection_id") != collection_id or od.get("database_id") != database_id or od.get("status") != "active":
                continue
            other = od.get("data") if isinstance(od.get("data"), dict) else {}
            otup = tuple(other.get(k) for k in keys)
            if otup == tup:
                return _log_and_return(_err("CONFLICT", f"Unique index violation on '{ix.get('key')}'.", index=ix.get("key")))

    now = _iso_now()
    row = {
        "id": document_id,
        "collection_id": collection_id,
        "database_id": database_id,
        "data": final,
        "permissions": permissions if bool(col.get("document_security")) else None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    docs.append(row)
    try:
        _save("documents.json", docs)
    except Exception as ex:
        return _log_and_return(_err("CONFLICT", "Failed to persist document.", detail=str(ex)))

    return _log_and_return({"document": row})

