        return _log_and_return(_err("VALIDATION_ERROR", "database_id must match ^db_[0-9A-Z]{26}$.", field="database_id"))
    if not isinstance(collection_id, str) or not re.match(r"^col_[0-9A-Z]{26}$", collection_id):
        return _log_and_return(_err("VALIDATION_ERROR", "collection_id must match ^col_[0-9A-Z]{26}$.", field="collection_id"))
    if not isinstance(key, str) or len(key) < 1:
        return _log_and_return(_err("VALIDATION_ERROR", "key must be a non-empty string.", field="key"))
    if not re.match(r"^[A-Za-z_][A-Za-z0-9_]{0,63}$", key):
        return _log_and_return(_err("VALIDATION_ERROR", "key must match ^[A-Za-z_][A-Za-z0-9_]{0,63}$.", field="key"))
    if type not in ("key", "unique", "fulltext"):
        return _log_and_return(_err("VALIDATION_ERROR", "type must be one of key|unique|fulltext.", field="type"))
    if not isinstance(attributes, list) or len(attributes) < 1:
        return _log_and_return(_err("VALIDATION_ERROR", "attributes must be a non-empty array.", field="attributes"))
    if len(attributes) > 32:
        return _log_and_return(_err("VALIDATION_ERROR", "attributes length must be between 1 and 32.", field="attributes"))
    for i, a in enumerate(attributes):
        if not isinstance(a, str) or not a:
            return _log_and_return(_err("VALIDATION_ERROR", "attributes entries must be non-empty strings.", field="attributes", index=i))

    if type == "fulltext":
        if orders is not None:
            return _log_and_return(_err("VALIDATION_ERROR", "orders must be null for fulltext indexes.", field="orders"))
    else:
        if orders is not None:
            if not isinstance(orders, list):
                return _log_and_return(_err("VALIDATION_ERROR", "orders must be an array when provided.", field="orders"))
            if len(orders) != len(attributes):
                return _log_and_return(_err("VALIDATION_ERROR", "orders must have the same length as attributes.", field="orders"))
            for i, o in enumerate(orders):
                if o not in ("ASC", "DESC"):
                    return _log_and_return(_err("VALIDATION_ERROR", "orders entries must be ASC or DESC.", field="orders", index=i))

    dbs = _load("databases.json")
    cols = _load("collections.json")
    attrs = _load("attributes.json")
    idxs = _load("indexes.json")
    if not isinstance(dbs, list): dbs = []
    if not isinstance(cols, list): cols = []
    if not isinstance(attrs, list): attrs = []
    if not isinstance(idxs, list): idxs = []

    db = next((d for d in dbs if d.get("id") == database_id and d.get("status") != "deleted"), None)
