    if not col:
        return _log_and_return(_err("NOT_FOUND", "Collection not found.", field="collection_id"))
    if col.get("status") != "active":
        return _log_and_return(_err("INVALID_TRANSITION", "Collection is not active.", field="collection_id"))

    for ix in idxs:
        if ix.get("collection_id") == collection_id and ix.get("status") != "deleted" and ix.get("key") == key:
            return _log_and_return(_err("CONFLICT", "An index with the same key already exists in the collection.", field="key"))

    # Validate referenced attribute keys exist and active
    active_attr_keys = {a.get("key") for a in attrs if a.get("collection_id") == collection_id and a.get("status") == "active" and isinstance(a.get("key"), str)}
    for a in attributes:
        if a not in active_attr_keys:
            return _log_and_return(_err("VALIDATION_ERROR", f"Referenced attribute key '{a}' does not exist or is not active.", field="attributes"))

    now = _iso_now()
    idx_id = f"idx_{int(time.time()*1000)}_{len(idxs)+1}"
    row = {
        "id": idx_id,
        "collection_id": collection_id,
        "key": key,
        "type": type,
        "attributes": attributes,
        "orders": orders if type != "fulltext" else None,
        "status": "building",
        "last_error": None,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    idxs.append(row)
    try:
        _save("indexes.json", idxs)
    except Exception as ex:
        return _log_and_return(_err("CONFLICT", "Failed to persist index.", detail=str(ex)))

    # Simulate build completion and transition to active (legal transition building -> active)
    # Appwrite builds asynchronously; in this offline store we complete immediately unless failure conditions exist.
    row["status"] = "active"
    row["updated_at"] = _iso_now()
    try:
        _save("indexes.json", idxs)
    except Exception as ex:
        return _log_and_return(_err("CONFLICT", "Failed to finalize index build.", detail=str(ex)))

    return _log_and_return({"index": row})

