def databases_delete_collection(database_id, collection_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0353000" if __import__("os").path.isdir("./environment_mix/0353000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, credential_id=None, details=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        latency_ms = None
        if started_at is not None:
            latency_ms = int((time.perf_counter() - started_at) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": ts,
        }
        if details is not None:
            row["details"] = details
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.perf_counter()
    endpoint = "databases_delete_collection"

    # Validate
    if not isinstance(database_id, str) or re.match(r"^db_[0-9A-Z]{26}$", database_id) is None:
        _log(endpoint, "error", started_at=started, details={"field": "database_id"})
        return _err("VALIDATION_ERROR", "Invalid database_id.", field="database_id")
    if not isinstance(collection_id, str) or re.match(r"^col_[0-9A-Z]{26}$", collection_id) is None:
        _log(endpoint, "error", started_at=started, details={"field": "collection_id"})
        return _err("VALIDATION_ERROR", "Invalid collection_id.", field="collection_id")

    databases = _load("databases.json")
    collections = _load("collections.json")
    attributes = _load("attributes.json")
    indexes = _load("indexes.json")
    documents = _load("documents.json")

    if not isinstance(databases, list) or not isinstance(collections, list) or not isinstance(attributes, list) or not isinstance(indexes, list) or not isinstance(documents, list):
        _log(endpoint, "error", started_at=started)
        return _err("CONFLICT", "Datastore is corrupted.")

    db = next((d for d in databases if d.get("id") == database_id), None)
    if db is None:
        _log(endpoint, "error", started_at=started)
        return _err("NOT_FOUND", "Database not found.")
    if db.get("status") == "deleted":
        _log(endpoint, "error", started_at=started)
        return _err("NOT_FOUND", "Database not found.")

    col = next((c for c in collections if c.get("id") == collection_id), None)
    if col is None or col.get("database_id") != database_id:
        _log(endpoint, "error", started_at=started)
        return _err("NOT_FOUND", "Collection not found.")
    if col.get("status") == "deleted":
        _log(endpoint, "error", started_at=started)
        return _err("NOT_FOUND", "Collection not found.")

    # Business rule: refuse deletion if any index is building
    building = [i for i in indexes if i.get("collection_id") == collection_id and i.get("status") == "building"]
    if building:
        _log(endpoint, "error", started_at=started)
        return _err("INVALID_TRANSITION", "Cannot delete collection while an index is building.", reason="index_building")

    now = _now()

    # Transition collection active->deleting->deleted (perform cascading workflow)
    current = col.get("status")
    if current == "active":
        col["status"] = "deleting"
        col["updated_at"] = now
        current = "deleting"
    if current != "deleting":
        _log(endpoint, "error", started_at=started)
        return _err("INVALID_TRANSITION", "Collection cannot be deleted from its current state.", status=col.get("status"))

    # Cascade delete: attributes, indexes, documents (logical deletes per lifecycle)
    # 1) Attributes: active->deleting->deleted
    for a in attributes:
        if a.get("collection_id") != collection_id:
            continue
        if a.get("status") == "deleted":
            continue
        if a.get("status") == "active":
            a["status"] = "deleting"
            a["updated_at"] = now
        if a.get("status") == "deleting":
            a["status"] = "deleted"
            a["updated_at"] = now
            a["deleted_at"] = now

    # 2) Indexes: building|active|failed->deleting->deleted (building already blocked)
    for ix in indexes:
        if ix.get("collection_id") != collection_id:
            continue
        if ix.get("status") == "deleted":
            continue
        if ix.get("status") in ("active", "failed"):
            ix["status"] = "deleting"
            ix["updated_at"] = now
        elif ix.get("status") == "building":
            # already blocked earlier, but keep safe
            _log(endpoint, "error", started_at=started)
            return _err("INVALID_TRANSITION", "Cannot delete collection while an index is building.", reason="index_building")
        if ix.get("status") == "deleting":
            ix["status"] = "deleted"
            ix["updated_at"] = now
            ix["deleted_at"] = now
            # align failed constraint
            if ix.get("status") != "failed":
                if "last_error" in ix and (ix.get("last_error") or "") != "":
                    # allow keeping, but schema says should be null/empty; set to empty
                    ix["last_error"] = ""

    # 3) Documents: active->deleted (do not physically remove)
    for doc in documents:
        if doc.get("collection_id") != collection_id:
            continue
        if doc.get("database_id") != database_id:
            continue
        if doc.get("status") == "deleted":
            continue
        if doc.get("status") == "active":
            doc["status"] = "deleted"
            doc["updated_at"] = now
            doc["deleted_at"] = now

    # Finalize collection deleting->deleted
    col["status"] = "deleted"
    col["updated_at"] = now
    col["deleted_at"] = now
    # constraint: cannot set enabled=true when status!='active'
    if col.get("enabled") is True:
        col["enabled"] = False

    _save("collections.json", collections)
    _save("attributes.json", attributes)
    _save("indexes.json", indexes)
    _save("documents.json", documents)

    _log(endpoint, "ok", started_at=started)
    return {"status": "success"}

