        if a.get("type") != "relationship":
            continue
        rel = a.get("relationship") if isinstance(a.get("relationship"), dict) else None
        if not rel:
            continue
        if rel.get("related_collection_id") == collection_id and rel.get("on_delete") == "restrict":
            rel_attrs.append((a, rel))

    if rel_attrs:
        # Load all docs once (already loaded)
        for (a, rel) in rel_attrs:
            key_on_related = rel.get("key_on_related")
            if not isinstance(key_on_related, str) or key_on_related == "":
                continue
            source_collection_id = a.get("collection_id")
            for d in documents:
                if d.get("status") != "active":
                    continue
                if d.get("collection_id") != source_collection_id:
                    continue
                data = d.get("data")
                if not isinstance(data, dict):
                    continue
                v = data.get(key_on_related)
                if v == document_id or (isinstance(v, list) and document_id in v):
                    _log(endpoint, "error", started_at=started)
                    return _err(
                        "CONFLICT",
                        "Cannot delete document due to restrict relationship references.",
                        relationship_attribute_id=a.get("id"),
                        relationship_key_on_related=key_on_related,
                        referencing_document_id=d.get("id"),
                    )

    now = _now()
    if doc.get("status") != "active":
        _log(endpoint, "error", started_at=started)
        return _err("INVALID_TRANSITION", "Document cannot be deleted from its current state.", status=doc.get("status"))

    doc["status"] = "deleted"
    doc["updated_at"] = now
    doc["deleted_at"] = now

    _save("documents.json", documents)
    _log(endpoint, "ok", started_at=started)
    return {"status": "success"}

