    t0 = time.time()
    endpoint = "databases_list"
    cred_used = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_logs():
        # request logs / counters are optional in this schema; implement if present
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            return "request_logs.json", logs
        return None, None

    def _log(status_code, error_code=None):
