            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        }
        logs.append(row)
        _save(fn, logs)

    def _validate():
        if limit is not None:
            if not isinstance(limit, int):
                return _err("VALIDATION_ERROR", "limit must be an integer")
            if limit < 1 or limit > 100:
                return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")
        if order_by is not None:
            if not isinstance(order_by, str):
                return _err("VALIDATION_ERROR", "order_by must be a string")
            if order_by not in ("created_at", "updated_at", "name", "status"):
                return _err("VALIDATION_ERROR", "Invalid order_by value")
