            if not isinstance(order_direction, str):
                return _err("VALIDATION_ERROR", "order_direction must be a string")
            if order_direction not in ("asc", "desc"):
                return _err("VALIDATION_ERROR", "Invalid order_direction value")
        if status is not None:
            if not isinstance(status, str):
                return _err("VALIDATION_ERROR", "status must be a string")
            if status not in ("active", "deleting", "deleted"):
                return _err("VALIDATION_ERROR", "Invalid status value")
