        row = {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "databases_list_indexes",
            "ts": now,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "credential_id": credential_id,
            "meta": meta or {}
        }
        logs.append(row)
        _save(reqlog_name, logs)

    # Validate ids
    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{26}$", database_id):
        _log(400, meta={"error": "bad_database_id"})
        return _err("VALIDATION_ERROR", "Malformed database_id.")
    if not isinstance(collection_id, str) or not re.match(r"^col_[0-9A-Z]{26}$", collection_id):
        _log(400, meta={"error": "bad_collection_id"})
        return _err("VALIDATION_ERROR", "Malformed collection_id.")

    if limit is None:
        limit_v = 25
    else:
        if not isinstance(limit, int):
            _log(400, meta={"error": "bad_limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 100:
            _log(400, meta={"error": "bad_limit_range"})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
        limit_v = limit

    if cursor is not None and not isinstance(cursor, str):
        _log(400, meta={"error": "bad_cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    allowed_order_by = {"created_at", "updated_at", "key", "type", "status"}
    if order_by is None:
        order_by_v = "created_at"
    else:
        if not isinstance(order_by, str) or order_by not in allowed_order_by:
            _log(400, meta={"error": "bad_order_by"})
            return _err("VALIDATION_ERROR", "Invalid order_by.")
        order_by_v = order_by

    allowed_dir = {"asc", "desc"}
    if order_direction is None:
        order_dir_v = "asc"
    else:
        if not isinstance(order_direction, str) or order_direction not in allowed_dir:
            _log(400, meta={"error": "bad_order_direction"})
            return _err("VALIDATION_ERROR", "Invalid order_direction.")
        order_dir_v = order_direction

    allowed_status = {"building", "active", "failed", "deleting", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(400, meta={"error": "bad_status_filter"})
            return _err("VALIDATION_ERROR", "Invalid status filter.")
    allowed_type = {"key", "unique", "fulltext"}
    if type is not None:
        if not isinstance(type, str) or type not in allowed_type:
            _log(400, meta={"error": "bad_type_filter"})
            return _err("VALIDATION_ERROR", "Invalid type filter.")

    # Resolve DB + collection
    dbs = _load("databases.json")
    cols = _load("collections.json")

    db = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id), None)
    if not db:
        _log(404, meta={"error": "db_not_found"})
        return _err("NOT_FOUND", "Database not found.")
    if db.get("status") == "deleted":
        _log(404, meta={"error": "db_deleted"})
        return _err("NOT_FOUND", "Database not found.")
    col = next((c for c in cols if isinstance(c, dict) and c.get("id") == collection_id and c.get("database_id") == database_id), None)
    if not col:
        _log(404, meta={"error": "collection_not_found"})
        return _err("NOT_FOUND", "Collection not found.")
    if col.get("status") == "deleted":
        _log(404, meta={"error": "collection_deleted"})
        return _err("NOT_FOUND", "Collection not found.")

    idxs = _load("indexes.json")
    if not isinstance(idxs, list):
        idxs = []

    # Filter by context and exclude deleted by default
    rows = []
    for ix in idxs:
        if not isinstance(ix, dict):
            continue
        if ix.get("collection_id") != collection_id:
            continue
        if ix.get("status") == "deleted":
            continue
        if status is not None and ix.get("status") != status:
            continue
        if type is not None and ix.get("type") != type:
            continue
        rows.append(ix)

    # Sorting (stable)
    def _sort_key(r):
        v = r.get(order_by_v)
        if v is None:
            return ""
        return v
    reverse = (order_dir_v == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor: opaque, but we implement as "after:<id>"
    start = 0
    if cursor:
        # find first row after cursor id
        try:
            cur_id = cursor
            if cursor.startswith("after:"):
                cur_id = cursor.split("after:", 1)[1]
            pos = next((i for i, r in enumerate(rows) if r.get("id") == cur_id), None)
            if pos is None:
                _log(400, meta={"error": "cursor_not_found"})
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start = pos + 1
        except Exception:
            _log(400, meta={"error": "cursor_parse_error"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = rows[start:start + limit_v]
    has_more = (start + limit_v) < len(rows)
    next_cursor = None
    if has_more and page:
        next_cursor = "after:" + str(page[-1].get("id"))

    _log(200, meta={"returned": len(page), "total": len(rows)})
    return {
        "total": len(rows),
        "limit": limit_v,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "indexes": page
    }

def databases_update(database_id, name=None, description=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0353000" if __import__("os").path.isdir("./environment_mix/0353000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    reqlog_name = None
    for cand in ("request_logs.json", "requests.json", "usage.json", "audit.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            reqlog_name = cand
            break

    def _log(status_code, meta=None):
        if not reqlog_name:
            return
        logs = _load(reqlog_name)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "databases_update",
            "ts": now,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save(reqlog_name, logs)

    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{26}$", database_id):
        _log(400, {"error": "bad_database_id"})
        return _err("VALIDATION_ERROR", "Malformed database_id.")

    if name is None and description is None:
        _log(400, {"error": "no_fields"})
        return _err("VALIDATION_ERROR", "At least one field (name or description) must be provided.")

    if name is not None:
        if not isinstance(name, str):
            _log(400, {"error": "bad_name_type"})
            return _err("VALIDATION_ERROR", "name must be a string.")
        if len(name) < 1 or len(name) > 128:
            _log(400, {"error": "bad_name_length"})
            return _err("VALIDATION_ERROR", "name length must be between 1 and 128.")

    if description is not None and not isinstance(description, str):
        _log(400, {"error": "bad_description_type"})
        return _err("VALIDATION_ERROR", "description must be a string.")

    dbs = _load("databases.json")
    if not isinstance(dbs, list):
        dbs = []

    db = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id), None)
    if not db:
        _log(404, {"error": "not_found"})
        return _err("NOT_FOUND", "Database not found.")
    if db.get("status") == "deleted":
        _log(404, {"error": "deleted"})
        return _err("NOT_FOUND", "Database not found.")

    if db.get("status") != "active":
        _log(409, {"error": "not_updatable_state", "status": db.get("status")})
        return _err("CONFLICT", "Database is not in an updatable state.", status=db.get("status"))

    # unique(name) where status != 'deleted'
    if name is not None and name != db.get("name"):
        for other in dbs:
            if not isinstance(other, dict):
                continue
            if other.get("id") == database_id:
                continue
            if other.get("status") != "deleted" and other.get("name") == name:
                _log(409, {"error": "duplicate_name"})
                return _err("CONFLICT", "Database name already exists.", field="name")

    changed = False
    if name is not None and name != db.get("name"):
        db["name"] = name
        changed = True
    if description is not None and description != db.get("description"):
        db["description"] = description
        changed = True

    if not changed:
        # idempotent update still writes updated_at? Real APIs usually do; but "no success without effect" applies to mutations
        # Here effect means record touched; if no field changes, treat as conflict-free no-op but still update updated_at to reflect request.
        db["updated_at"] = now
        _save("databases.json", dbs)
        _log(200, {"updated": True, "idempotent": True})
        return {"database": db}

    db["updated_at"] = now
    _save("databases.json", dbs)
    _log(200, {"updated": True})
    return {"database": db}

def databases_update_boolean_attribute(database_id, collection_id, attribute_id, key=None, required=None, default_value=None, array=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0353000" if __import__("os").path.isdir("./environment_mix/0353000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    reqlog_name = None
    for cand in ("request_logs.json", "requests.json", "usage.json", "audit.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            reqlog_name = cand
            break

    def _log(status_code, meta=None):
        if not reqlog_name:
            return
        logs = _load(reqlog_name)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": "databases_update_boolean_attribute",
            "ts": now,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {}
        })
        _save(reqlog_name, logs)

    # Validate IDs
    if not isinstance(database_id, str) or not re.match(r"^db_[0-9A-Z]{26}$", database_id):
        _log(400, {"error": "bad_database_id"})
        return _err("VALIDATION_ERROR", "Malformed database_id.")
    if not isinstance(collection_id, str) or not re.match(r"^col_[0-9A-Z]{26}$", collection_id):
        _log(400, {"error": "bad_collection_id"})
        return _err("VALIDATION_ERROR", "Malformed collection_id.")
    if not isinstance(attribute_id, str) or not re.match(r"^attr_[0-9A-Z]{26}$", attribute_id):
        _log(400, {"error": "bad_attribute_id"})
        return _err("VALIDATION_ERROR", "Malformed attribute_id.")

    if key is None and required is None and default_value is None and array is None:
        _log(400, {"error": "no_fields"})
        return _err("VALIDATION_ERROR", "At least one field must be provided for update.")

    # Validate fields
    if key is not None:
        if not isinstance(key, str) or len(key) < 1:
            _log(400, {"error": "bad_key"})
            return _err("VALIDATION_ERROR", "key must be a non-empty string.")
        if len(key) > 64:
            _log(400, {"error": "bad_key_length"})
            return _err("VALIDATION_ERROR", "key length must be <= 64.")
        if not re.match(r"^[A-Za-z_][A-Za-z0-9_]{0,63}$", key):
            _log(400, {"error": "bad_key_pattern"})
            return _err("VALIDATION_ERROR", "key must match ^[A-Za-z_][A-Za-z0-9_]{0,63}$.")

    if required is not None and not isinstance(required, bool):
        _log(400, {"error": "bad_required"})
        return _err("VALIDATION_ERROR", "required must be a boolean.")

    if default_value is not None and not isinstance(default_value, bool):
        _log(400, {"error": "bad_default_value"})
        return _err("VALIDATION_ERROR", "default_value must be a boolean.")

    if array is not None and not isinstance(array, bool):
        _log(400, {"error": "bad_array"})
        return _err("VALIDATION_ERROR", "array must be a boolean.")

    dbs = _load("databases.json")
    cols = _load("collections.json")
    attrs = _load("attributes.json")
    docs = _load("documents.json")
    idxs = _load("indexes.json")

    if not isinstance(dbs, list): dbs = []
    if not isinstance(cols, list): cols = []
    if not isinstance(attrs, list): attrs = []
    if not isinstance(docs, list): docs = []
    if not isinstance(idxs, list): idxs = []

    db = next((d for d in dbs if isinstance(d, dict) and d.get("id") == database_id), None)
    if not db or db.get("status") == "deleted":
        _log(404, {"error": "db_not_found"})
        return _err("NOT_FOUND", "Database not found.")

    col = next((c for c in cols if isinstance(c, dict) and c.get("id") == collection_id and c.get("database_id") == database_id), None)
    if not col or col.get("status") == "deleted":
        _log(404, {"error": "collection_not_found"})
        return _err("NOT_FOUND", "Collection not found.")

    if col.get("status") != "active":
        _log(409, {"error": "collection_not_active"})
        return _err("CONFLICT", "Collection is not in an updatable state.", status=col.get("status"))

    attr = next((a for a in attrs if isinstance(a, dict) and a.get("id") == attribute_id and a.get("collection_id") == collection_id), None)
    if not attr or attr.get("status") == "deleted":
        _log(404, {"error": "attribute_not_found"})
        return _err("NOT_FOUND", "Attribute not found.")

    # Must only modify active attribute and must be boolean
    if attr.get("status") != "active":
        _log(409, {"error": "attribute_not_active"})
        return _err("CONFLICT", "Attribute is not in an updatable state.", status=attr.get("status"))
    if attr.get("type") != "boolean":
        _log(409, {"error": "wrong_type"})
        return _err("CONFLICT", "Attribute type mismatch; expected boolean.", type=attr.get("type"))

    # Unique (collection_id, key) where status != 'deleted'
    if key is not None and key != attr.get("key"):
        for other in attrs:
            if not isinstance(other, dict):
                continue
            if other.get("collection_id") != collection_id:
                continue
            if other.get("id") == attribute_id:
                continue
            if other.get("status") != "deleted" and other.get("key") == key:
                _log(409, {"error": "duplicate_key"})
                return _err("CONFLICT", "Attribute key already exists in this collection.", field="key")

        # Refuse rename if referenced by any non-deleted index.attributes
        for ix in idxs:
            if not isinstance(ix, dict):
                continue
            if ix.get("collection_id") != collection_id:
                continue
            if ix.get("status") == "deleted":
                continue
            attrs_in_ix = ix.get("attributes")
            if isinstance(attrs_in_ix, list) and attr.get("key") in attrs_in_ix:
                _log(409, {"error": "attribute_referenced_by_index"})
                return _err("CONFLICT", "Cannot change attribute key because it is referenced by an index.", index_id=ix.get("id"))

        # Refuse rename if referenced as key_on_related in any relationship attribute
        for a in attrs:
            if not isinstance(a, dict):
                continue
            if a.get("type") != "relationship" or a.get("status") == "deleted":
                continue
            rel = a.get("relationship")
            if isinstance(rel, dict) and rel.get("key_on_related") == attr.get("key") and rel.get("related_collection_id") == collection_id:
                _log(409, {"error": "attribute_referenced_by_relationship"})
                return _err("CONFLICT", "Cannot change attribute key because it is used as key_on_related in a relationship.", relationship_attribute_id=a.get("id"))

    # Build prospective attribute
    new_attr = dict(attr)
    if key is not None:
        new_attr["key"] = key
    if required is not None:
        new_attr["required"] = required
    if default_value is not None:
        new_attr["default_value"] = default_value
    if array is not None:
        new_attr["array"] = array

    # Enforce boolean constraints: min/max must be null; enum_values/relationship must be null
    if new_attr.get("min") is not None or new_attr.get("max") is not None:
        _log(400, {"error": "boolean_min_max_not_allowed"})
        return _err("VALIDATION_ERROR", "Boolean attributes cannot have min/max.")
    if new_attr.get("enum_values") is not None:
        _log(400, {"error": "boolean_enum_values_not_allowed"})
        return _err("VALIDATION_ERROR", "Boolean attributes cannot have enum_values.")
    if new_attr.get("relationship") is not None:
        _log(400, {"error": "boolean_relationship_not_allowed"})
        return _err("VALIDATION_ERROR", "Boolean attributes cannot have relationship configuration.")

    # Validate existing documents won't become invalid with new schema:
    # - if required becomes true, all active docs must have non-null for this key
    # - if array changes, existing values must match (bool vs [bool])
    old_key = attr.get("key")
    new_key = new_attr.get("key")
    req_flag = bool(new_attr.get("required"))
    arr_flag = bool(new_attr.get("array"))

    def _is_bool(v):
        return isinstance(v, bool)

    invalid_docs = []
    for d in docs:
        if not isinstance(d, dict):
            continue
        if d.get("database_id") != database_id or d.get("collection_id") != collection_id:
            continue
        if d.get("status") != "active":
            continue
        data = d.get("data")
        if not isinstance(data, dict):
            continue  # existing invalid data not fixed here
        # if key renamed, treat value moving? Implementation does not migrate document keys automatically.
        # Therefore, if key changes, documents would "lose" the field; required would break.
        # Also indexes may reference old key (handled above).
        if new_key != old_key:
            if req_flag:
                invalid_docs.append(d.get("id"))
                continue
            # array/type validation on new key only if present; but it won't be present if unchanged data.
            continue

        if req_flag:
            if old_key not in data or data.get(old_key) is None:
                invalid_docs.append(d.get("id"))
                continue

        if old_key in data and data.get(old_key) is not None:
            v = data.get(old_key)
            if arr_flag:
                if not isinstance(v, list) or any((x is not None and not _is_bool(x)) for x in v):
                    invalid_docs.append(d.get("id"))
                    continue
            else:
                if not _is_bool(v):
                    invalid_docs.append(d.get("id"))
                    continue

    if invalid_docs:
        _log(400, {"error": "documents_would_be_invalid", "count": len(invalid_docs)})
        return _err("VALIDATION_ERROR", "Update would make existing documents invalid under the active schema.", invalid_documents=invalid_docs[:50], invalid_count=len(invalid_docs))

    # Apply update
    changed = False
    for k in ("key", "required", "default_value", "array"):
        if (k in new_attr) and new_attr.get(k) != attr.get(k):
            attr[k] = new_attr.get(k)
            changed = True

    if not changed:
        # touch updated_at as idempotent effect
        attr["updated_at"] = now
        _save("attributes.json", attrs)
        _log(200, {"updated": True, "idempotent": True})
        return {"attribute": attr}

    attr["updated_at"] = now
    _save("attributes.json", attrs)
    _log(200, {"updated": True})
    return {"attribute": attr}

