    # cannot set enabled=true when status!='active' (already ensured), but allow enabled=false here.
    if enabled is not None and enabled is True and col.get("status") != "active":
        _log(409, {"error": "enabled_true_not_allowed"})
        return _err("CONFLICT", "Cannot enable collection unless it is active.")

    # unique(database_id, name) where status != 'deleted'
    if name is not None and name != col.get("name"):
        for other in cols:
            if not isinstance(other, dict):
                continue
            if other.get("id") == collection_id:
                continue
            if other.get("database_id") != database_id:
                continue
            if other.get("status") != "deleted" and other.get("name") == name:
                _log(409, {"error": "duplicate_name"})
                return _err("CONFLICT", "Collection name already exists in this database.", field="name")

    changed = False
    if name is not None and name != col.get("name"):
        col["name"] = name
        changed = True
    if description is not None and description != col.get("description"):
        col["description"] = description
        changed = True
    if document_security is not None and document_security != col.get("document_security"):
        col["document_security"] = document_security
        changed = True
    if enabled is not None and enabled != col.get("enabled"):
        col["enabled"] = enabled
        changed = True

    # Constraint: document_security in (true,false), enabled in (true,false) -> ensure present
    if "document_security" not in col or not isinstance(col.get("document_security"), bool):
        _log(400, {"error": "document_security_missing_or_invalid"})
        return _err("VALIDATION_ERROR", "document_security must be a boolean.")
    if "enabled" not in col or not isinstance(col.get("enabled"), bool):
        _log(400, {"error": "enabled_missing_or_invalid"})
        return _err("VALIDATION_ERROR", "enabled must be a boolean.")

    if not changed:
        col["updated_at"] = now
        _save("collections.json", cols)
        _log(200, {"updated": True, "idempotent": True})
        return {"collection": col}

    col["updated_at"] = now
    _save("collections.json", cols)
    _log(200, {"updated": True})
    return {"collection": col}

def databases_update_datetime_attribute(database_id, collection_id, attribute_id, key=None, required=None, default_value=None, array=None, min=None, max=None, format=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0353000" if __import__("os").path.isdir("./environment_mix/0353000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    usage = _load("usage.json")
    if not isinstance(usage, dict):
        usage = {}

    def _log(status, error_code=None):
        entry = {
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(request_logs)+1}",
            "endpoint": "databases_update_datetime_attribute",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": error_code,
            "credential_id": None,
        }
        request_logs.append(entry)
        usage["calls_total"] = int(usage.get("calls_total", 0)) + 1
        usage["calls_databases_update_datetime_attribute"] = int(usage.get("calls_databases_update_datetime_attribute", 0)) + 1
        _save("request_logs.json", request_logs)
        _save("usage.json", usage)

    # Rate limit / quota (if configured)
    limits = _load("limits.json")
    if isinstance(limits, dict):
        rl = limits.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl > 0:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
            c = 0
            for r in request_logs:
                ts = r.get("timestamp")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        c += 1
            if c >= rl:
                _log("error", "RATE_LIMIT")
                return _err("RATE_LIMIT", "Rate limit exceeded")
        quota = limits.get("quota_total_calls")
        if isinstance(quota, int) and quota >= 0:
            if int(usage.get("calls_total", 0)) >= quota:
                _log("error", "QUOTA_EXCEEDED")
                return _err("QUOTA_EXCEEDED", "Quota exceeded")

    # Validate IDs
    if not (isinstance(database_id, str) and re.match(r"^db_[0-9A-Z]{26}$", database_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid database_id")
    if not (isinstance(collection_id, str) and re.match(r"^col_[0-9A-Z]{26}$", collection_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid collection_id")
    if not (isinstance(attribute_id, str) and re.match(r"^attr_[0-9A-Z]{26}$", attribute_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid attribute_id")

    if key is not None and not isinstance(key, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "key must be a string")
    if required is not None and not isinstance(required, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "required must be a boolean")
    if array is not None and not isinstance(array, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "array must be a boolean")
    if min is not None and not isinstance(min, (int, float)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min must be a number")
    if max is not None and not isinstance(max, (int, float)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max must be a number")
    if min is not None and max is not None and float(min) > float(max):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min must be <= max")
    if format is not None and not isinstance(format, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "format must be a string")
    if key is not None:
        if not re.match(r"^[A-Za-z_][A-Za-z0-9_]{0,63}$", key):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "key does not match required pattern")

    # Load rows
    databases = _load("databases.json")
    collections = _load("collections.json")
    attributes = _load("attributes.json")
    documents = _load("documents.json")

    db = next((d for d in databases if d.get("id") == database_id), None)
    if not db or db.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not found")
    col = next((c for c in collections if c.get("id") == collection_id and c.get("database_id") == database_id), None)
    if not col or col.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Collection not found")
    if col.get("status") != "active":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Collection is not active")

    attr = next((a for a in attributes if a.get("id") == attribute_id and a.get("collection_id") == collection_id), None)
    if not attr or attr.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Attribute not found")
    if attr.get("status") != "active":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Attribute is not active")
    if attr.get("type") != "datetime":
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Attribute is not a datetime attribute")

    # Compose candidate update
    new_attr = dict(attr)
    if key is not None:
        # uniqueness within collection among non-deleted
        for a in attributes:
            if a.get("collection_id") == collection_id and a.get("status") != "deleted" and a.get("id") != attribute_id:
                if a.get("key") == key:
                    _log("error", "CONFLICT")
                    return _err("CONFLICT", "Attribute key already exists in this collection")
        new_attr["key"] = key
    if required is not None:
        new_attr["required"] = required
    if default_value is not None:
        # default_value must be a valid datetime or list of datetimes if array=true (or resulting array)
        pass
        new_attr["default_value"] = default_value
    if array is not None:
        new_attr["array"] = array
    if min is not None:
        new_attr["min"] = min
    if max is not None:
        new_attr["max"] = max
    if format is not None:
        new_attr["format"] = format

    # Enforce boolean/min/max constraints for datetime
    if new_attr.get("min") is not None and not isinstance(new_attr.get("min"), (int, float)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min must be a number")
    if new_attr.get("max") is not None and not isinstance(new_attr.get("max"), (int, float)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max must be a number")
    if new_attr.get("min") is not None and new_attr.get("max") is not None and float(new_attr["min"]) > float(new_attr["max"]):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "min must be <= max")

    # Validate format (lightweight; accept None or known identifiers)
    allowed_formats = {None, "", "iso8601", "date", "datetime", "rfc3339"}
    if new_attr.get("format") not in allowed_formats:
        # allow custom vendor-like strings but reject obviously invalid types already handled
        if not isinstance(new_attr.get("format"), str) or len(new_attr.get("format")) > 64:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported format")

    def _parse_dt(v):
        if isinstance(v, (int, float)):
            # unix seconds
            try:
                return datetime.datetime.utcfromtimestamp(float(v))
            except Exception:
                return None
        if isinstance(v, str):
            s = v.strip()
            # accept Z
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    def _validate_dt_value(v):
        dt = _parse_dt(v)
        if dt is None:
            return False
        # min/max treated as epoch seconds if numeric constraints provided
        if new_attr.get("min") is not None:
            mn = datetime.datetime.utcfromtimestamp(float(new_attr["min"]))
            if dt.replace(tzinfo=None) < mn:
                return False
        if new_attr.get("max") is not None:
            mx = datetime.datetime.utcfromtimestamp(float(new_attr["max"]))
            if dt.replace(tzinfo=None) > mx:
                return False
        return True

    # Validate default_value
    dv = new_attr.get("default_value", None)
    if dv is not None:
        if bool(new_attr.get("array")):
            if not isinstance(dv, list):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "default_value must be an array when array=true")
            if not all(_validate_dt_value(x) for x in dv):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "default_value contains invalid datetime values")
        else:
            if isinstance(dv, list):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "default_value must not be an array when array=false")
            if not _validate_dt_value(dv):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "default_value is not a valid datetime")

    # Validate existing documents would still pass schema for this attribute (required/type/min/max)
    old_key = attr.get("key")
    new_key = new_attr.get("key")
    docs = [d for d in documents if d.get("database_id") == database_id and d.get("collection_id") == collection_id and d.get("status") == "active"]
    for d in docs:
        data = d.get("data")
        if not isinstance(data, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Existing document has invalid data")
        # handle rename: if key changed, treat value under old_key as now under new_key for validation
        has_new = new_key in data
        has_old = old_key in data
        val = None
        present = False
        if has_new:
            val = data.get(new_key)
            present = True
        elif has_old and new_key != old_key:
            val = data.get(old_key)
            present = True
        if new_attr.get("required"):
            if (not present) or (val is None):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Schema change would make existing document {d.get('id')} invalid (missing required '{new_key}')")
        if present and val is not None:
            if bool(new_attr.get("array")):
                if not isinstance(val, list) or not all(_validate_dt_value(x) for x in val):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Schema change would make existing document {d.get('id')} invalid (field '{new_key}')")
            else:
                if isinstance(val, list) or not _validate_dt_value(val):
                    _log("error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"Schema change would make existing document {d.get('id')} invalid (field '{new_key}')")

    # Apply update
    new_attr["updated_at"] = now
    # Ensure deleted_at constraint
    if new_attr.get("status") != "deleted":
        new_attr["deleted_at"] = None

    for i, a in enumerate(attributes):
        if a.get("id") == attribute_id:
            attributes[i] = new_attr
            break

    _save("attributes.json", attributes)
    _log("ok")
    return {"attribute": new_attr}

def databases_update_document(database_id, collection_id, document_id, data, permissions=None, **_extra):
