        usage["calls_databases_update_document"] = int(usage.get("calls_databases_update_document", 0)) + 1
        _save("request_logs.json", request_logs)
        _save("usage.json", usage)

    limits = _load("limits.json")
    if isinstance(limits, dict):
        rl = limits.get("rate_limit_per_minute")
        if isinstance(rl, int) and rl > 0:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(minutes=1)
            c = 0
            for r in request_logs:
                ts = r.get("timestamp")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        c += 1
            if c >= rl:
                _log("error", "RATE_LIMIT")
                return _err("RATE_LIMIT", "Rate limit exceeded")
        quota = limits.get("quota_total_calls")
        if isinstance(quota, int) and quota >= 0:
            if int(usage.get("calls_total", 0)) >= quota:
                _log("error", "QUOTA_EXCEEDED")
                return _err("QUOTA_EXCEEDED", "Quota exceeded")

    if not (isinstance(database_id, str) and re.match(r"^db_[0-9A-Z]{26}$", database_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid database_id")
    if not (isinstance(collection_id, str) and re.match(r"^col_[0-9A-Z]{26}$", collection_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid collection_id")
    if not (isinstance(document_id, str) and re.match(r"^doc_[0-9A-Z]{26}$", document_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid document_id")
    if not isinstance(data, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "data must be an object")
    if permissions is not None and not isinstance(permissions, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "permissions must be an object")

    databases = _load("databases.json")
    collections = _load("collections.json")
    attributes = _load("attributes.json")
    indexes = _load("indexes.json")
    documents = _load("documents.json")

    db = next((d for d in databases if d.get("id") == database_id), None)
    if not db or db.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Database not found")
    col = next((c for c in collections if c.get("id") == collection_id and c.get("database_id") == database_id), None)
    if not col or col.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Collection not found")

    if col.get("enabled") is not True:
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Collection is disabled")
    if col.get("status") != "active":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Collection is not active")

    doc = next((d for d in documents if d.get("id") == document_id), None)
    if not doc or doc.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Document not found")
    if doc.get("collection_id") != collection_id or doc.get("database_id") != database_id:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Document not found in this collection/database")

    if col.get("document_security") is False and permissions is not None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "permissions must be null when document_security is false")

    # Active attributes for validation
    col_attrs = [a for a in attributes if a.get("collection_id") == collection_id and a.get("status") == "active"]
    attr_by_key = {a.get("key"): a for a in col_attrs if isinstance(a.get("key"), str)}
    allowed_keys = set(attr_by_key.keys())

    # Merge update (partial merge, Appwrite-like)
    merged = {}
    existing = doc.get("data")
    if isinstance(existing, dict):
        merged.update(existing)
    merged.update(data)

    # Reject unknown fields
    unknown = [k for k in merged.keys() if k not in allowed_keys]
    if unknown:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unknown fields in document data", fields=unknown)

    # Validators
    def _is_email(s):
        if not isinstance(s, str):
            return False
        if len(s) > 320 or len(s) < 3:
            return False
        return re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s) is not None

    def _parse_dt(v):
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(float(v))
            except Exception:
                return None
        if isinstance(v, str):
            try:
                return datetime.datetime.fromisoformat(v.strip().replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    def _validate_value(attr, v):
        if v is None:
            return True
        t = attr.get("type")
        arr = bool(attr.get("array"))
        if arr:
            if not isinstance(v, list):
                return False
            return all(_validate_value({**attr, "array": False}, x) for x in v)

        if t == "string":
            if not isinstance(v, str): return False
            mn, mx = attr.get("min"), attr.get("max")
            if mn is not None and len(v) < float(mn): return False
            if mx is not None and len(v) > float(mx): return False
            return True
        if t == "integer":
            if not isinstance(v, int) or isinstance(v, bool): return False
            mn, mx = attr.get("min"), attr.get("max")
            if mn is not None and v < int(mn): return False
            if mx is not None and v > int(mx): return False
            return True
        if t == "float":
            if not isinstance(v, (int, float)) or isinstance(v, bool): return False
            mn, mx = attr.get("min"), attr.get("max")
            if mn is not None and float(v) < float(mn): return False
            if mx is not None and float(v) > float(mx): return False
            return True
        if t == "boolean":
            return isinstance(v, bool)
        if t == "datetime":
            dt = _parse_dt(v)
            if dt is None: return False
            mn, mx = attr.get("min"), attr.get("max")
            if mn is not None:
                if dt.replace(tzinfo=None) < datetime.datetime.utcfromtimestamp(float(mn)): return False
            if mx is not None:
                if dt.replace(tzinfo=None) > datetime.datetime.utcfromtimestamp(float(mx)): return False
            return True
        if t == "email":
            if not _is_email(v): return False
            mn, mx = attr.get("min"), attr.get("max")
            if mn is not None and len(v) < float(mn): return False
            if mx is not None and len(v) > float(mx): return False
            return True
        if t == "url":
            if not isinstance(v, str): return False
            if not re.match(r"^https?://", v): return False
            mn, mx = attr.get("min"), attr.get("max")
            if mn is not None and len(v) < float(mn): return False
            if mx is not None and len(v) > float(mx): return False
            return True
        if t == "ip":
            if not isinstance(v, str): return False
            if not (re.match(r"^\d{1,3}(\.\d{1,3}){3}$", v) or ":" in v): return False
            mn, mx = attr.get("min"), attr.get("max")
            if mn is not None and len(v) < float(mn): return False
            if mx is not None and len(v) > float(mx): return False
            return True
        if t == "enum":
            ev = attr.get("enum_values")
            if not isinstance(ev, list) or not all(isinstance(x, str) for x in ev): return False
            return isinstance(v, str) and v in ev
        if t == "relationship":
            # Stored value is application-defined; accept string or list for now, but require proper array handling
            return isinstance(v, str)
        return False

    # Required fields present and type constraints
    for a in col_attrs:
        k = a.get("key")
        if not isinstance(k, str):
            continue
        if a.get("required") is True:
            if k not in merged or merged.get(k) is None:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Missing required attribute '{k}'")
        if k in merged:
            if not _validate_value(a, merged.get(k)):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Invalid value for attribute '{k}'")

    # Unique index enforcement across active documents
    active_unique_indexes = [
        ix for ix in indexes
        if ix.get("collection_id") == collection_id and ix.get("status") == "active" and ix.get("type") == "unique"
    ]
    active_docs = [
        d for d in documents
        if d.get("collection_id") == collection_id and d.get("database_id") == database_id and d.get("status") == "active" and d.get("id") != document_id
    ]
    for ix in active_unique_indexes:
        keys = ix.get("attributes")
        if not isinstance(keys, list) or not keys:
            continue
        tup = tuple(merged.get(k) for k in keys)
        for od in active_docs:
            od_data = od.get("data")
