        log_row["status"] = "error"
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
    finally:
        try:
            log_row["latency_ms"] = int((time.time() - _t0) * 1000)
            reqlogs.append(log_row)
            _save("request_logs.json", reqlogs)
        except Exception:
            pass
